                result.Elements.Add(httpsBindingElement);
                return result;
            }
            throw new System.InvalidOperationException(string.Format("Could not find endpoint with name \'{0}\'.", endpointConfiguration));
        }
        
        private static System.ServiceModel.EndpointAddress GetEndpointAddress(EndpointConfiguration endpointConfiguration)
        {
            if ((endpointConfiguration == EndpointConfiguration.wsRPSSoap))
            {
                return new System.ServiceModel.EndpointAddress("https://www.barueri.sp.gov.br/nfeservice/wsrps.asmx");
            }
            if ((endpointConfiguration == EndpointConfiguration.wsRPSSoap12))
            {
                return new System.ServiceModel.EndpointAddress("https://www.barueri.sp.gov.br/nfeservice/wsrps.asmx");
            }
            throw new System.InvalidOperationException(string.Format("Could not find endpoint with name \'{0}\'.", endpointConfiguration));
        }
        
        public enum EndpointConfiguration
        {
            
            wsRPSSoap,
            
            wsRPSSoap12,
        }
    }
